nav=[('/find/','找門市'),('/how-it-works/','怎麼玩'),('/spaces/','空間體驗'),('/app/','ONE APP'),('/franchise/','加盟 ONE'),('/about/','品牌故事')]
def link(url,text,cl='text-link'):return f'<a class="{cl}" href="{url}">{text}</a>'
def section(body,cl='',id=''):return f'<section class="section {cl}"'+(f' id="{id}"' if id else '')+f'><div class="wrap">{body}</div></section>'
def shot(name,alt,cl=''):
 return f'<button class="actual-shot {cl}" data-image="/assets/{name}" data-caption="{alt}" aria-label="放大{alt}"><img src="/assets/{name}" alt="{alt}" loading="lazy"><span>實際產品畫面 <b>放大查看 ↗</b></span></button>'
def photo(name,alt,cl=''):return f'<figure class="photo {cl}"><img src="/images/{name}.jpg" alt="{alt}" loading="lazy"><figcaption>{alt}</figcaption></figure>'
def intro(title,desc,tag=''):return section(f'<div class="page-intro">'+(f'<p class="eyebrow">{tag}</p>' if tag else '')+f'<h1>{title}</h1><p>{desc}</p></div>','intro')
def proof():return section(f'<div class="proof"><div><strong>{stats["storesDisplay"]}</strong><span>全台品牌門市</span></div><div><strong>{stats["members"]:,}</strong><span>品牌累積會員</span></div><div><strong>{stats["founded"]}</strong><span>第一間 ONE 開始</span></div></div><p class="caption">更新 {stats["updatedAt"]} · {stats["note"]}</p>','proof-section')
def finder():return f'''<div class="finder" data-finder><form class="finder-controls"><label>選擇縣市<select name="city"><option value="">全台門市</option></select></label><label>搜尋門市或地址<input name="search" type="search" placeholder="例如：西屯、一中" autocomplete="off"></label><button type="button" class="button secondary" data-nearby>找附近門市</button></form><p class="caption" data-directory-date>正在讀取門市資料…</p><p role="status" data-result-status></p><div class="store-list" data-stores></div><button class="button secondary" data-more type="button" hidden>顯示更多門市</button><noscript><p>請開啟 JavaScript 使用門市篩選，或直接進入 ONE 預約系統。</p></noscript><p class="finder-note">門市照片、價格與最新空檔，請在各店預約頁查看。官網不顯示未確認的即時空位。</p>{link(BOOK,'開啟 ONE 全台門市 ↗')}</div>'''
def steps():return '<ol class="steps">'+''.join(f'<li><span>0{i}</span><h3>{a}</h3><p>{b}</p></li>' for i,(a,b) in enumerate([('找門市','選一間方便集合的 ONE。'),('選座位／包廂','查看照片、設備與空檔。'),('APP 預約付款','先看清楚時段與費用。'),('到店開始','依訂單及門市指引使用。')],1))+'</ol>'
def gallery():
 items=json.loads((R/'data/space-photos.json').read_text())
 return '<div class="gallery" aria-label="ONE 實際門店相簿">'+''.join(f'<button class="gallery-item" data-image="/images/{item["name"]}.jpg" data-caption="{item["caption"]}" aria-label="放大{item["caption"]}"><img src="/images/{item["name"]}.jpg" alt="{item["caption"]}" loading="lazy"><span>{item["caption"]} ↗</span></button>' for item in items)+'</div><p class="caption">左右滑動，點照片可放大。皆為實際門市照片；設備與配置以各店現況為準。</p>'

def appstory():
 items=[('找一間喜歡的店','依地點找門市，看看店內環境。','one-stores-20261007.png'),('選好座位與時間','實際空檔與可用方案，在預約頁查看。','one-booking-20261007.png'),('確認費用，再付款','確認門市、日期、時段與付款金額。','one-checkout-20261007.png')]
 return '<div class="app-story" data-story><div class="story-copy"><h2>下一次相聚，<br>用 ONE 安排。</h2><div role="tablist" aria-label="ONE APP 操作">'+''.join(f'<button role="tab" id="app-tab-{i}" aria-controls="app-panel-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-story-tab="{i}"><span>0{i+1}</span><div><h3>{a}</h3><p>{b}</p></div></button>' for i,(a,b,c) in enumerate(items))+'</div>'+link(BOOK,'開啟 ONE，查看座位','button')+'</div><div class="story-visual">'+''.join(f'<div role="tabpanel" id="app-panel-{i}" aria-labelledby="app-tab-{i}" {"hidden" if i else ""}>'+shot(c,a)+'</div>' for i,(a,b,c) in enumerate(items))+'</div></div>'
scenarios=[('今天晚上還有位置嗎？','先選門市與日期','最新空檔會隨訂單變動，請開啟門市預約頁查看；需要協助時可聯絡客服。','/find/','查門市空檔'),('這間店怎麼計費？','先看方案，再付款','各店依座位、日期及時段提供方案，預約前會顯示應付金額。','/find/','查各店價格'),('麻將桌沒反應怎麼辦？','先確認訂單是否開始','確認訂單時段與現場電源指示；請勿拆機或自行維修，交由客服協助判斷。',LINE,'聯絡客服'),('可以延長時間嗎？','先查看後續是否可預約','開啟目前訂單查看加時入口；是否能續時及費用，以系統顯示為準。',BOOK,'開啟我的訂單')]
def support():return '<div class="support-demo" data-support><div><h2>有問題，<br>直接問。</h2><p>先找答案，需要協助再接上客服。</p><div class="question-buttons" role="tablist" aria-label="常見客服情境">'+''.join(f'<button role="tab" id="question-{i}" aria-controls="answer-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-question="{i}">{a}</button>' for i,(a,b,c,d,f) in enumerate(scenarios))+'</div></div><div class="support-answer">'+''.join(f'<div role="tabpanel" id="answer-{i}" aria-labelledby="question-{i}" {"hidden" if i else ""}><span class="eyebrow">常見問題指引</span><h3>{b}</h3><p>{c}</p>{link(d,f,"button secondary")}</div>' for i,(a,b,c,d,f) in enumerate(scenarios))+'<p class="caption">這是操作指引，不是即時 AI 對話。AI 查位、電話與轉接服務依門市開通情況提供。</p><div class="actions">'+link(LINE,'LINE 詢問','button')+link('tel:0970199296','打電話詢問','button secondary')+'</div></div></div>'
def system():return '<div class="system-story"><div class="system-copy"><p class="eyebrow">ONE 營運系統</p><h2>顧客用得順，<br>店家看得清。</h2><p>從預約到現場，讓同一筆訂單接好每一步。</p><ol class="flow"><li>顧客預約</li><li>線上支付、成立訂單</li><li>依訂單時段連動控電</li><li>現場自助收款</li><li>後台查看桌況與營收</li></ol>'+link('/franchise/#pricing','看方案包含什麼')+'</div><div class="system-images">'+shot('one-admin-20261007.png','ONE 店家後台・營運總覽')+'<button class="actual-shot kiosk-photo" data-image="/images/one-guangcai-kiosk.jpg" data-caption="嘉義光彩店・現場自助繳費機" aria-label="放大現場自助繳費機照片"><img src="/images/one-guangcai-kiosk.jpg" alt="嘉義光彩店現場使用的自助繳費機" loading="lazy"><span>門市實際設備 <b>放大查看 ↗</b></span></button>'+'<p class="caption">後台為真實介面，營收不代表單店收益。繳費機攝於嘉義光彩店，支援現金與 LINE Pay；各店配置依實際設備為準。</p></div></div>'
